    public <T> T asOf(String sheetId, LocalDate date, Supplier<T> read) {
        ReentrantLock lock = shown.computeIfAbsent(sheetId, k -> new ReentrantLock());
        lock.lock();
        try {
            return rolledBack.execute(status -> {
                status.setRollbackOnly();
                put(sheetId, date);
                return read.get();
            });
        } finally {
            lock.unlock();
        }
    }

